import{_ as n,C as i,o as a,c as r,a3 as t,b as l,w as s,a as h,E as d,a4 as p}from"./chunks/framework.DhF4LrUq.js";const c="/shipperdog/snapshot/screenshots/console-ota-rollout.png",u="/shipperdog/snapshot/screenshots/console-ota-dashboard.png",E=JSON.parse('{"title":"Run OTA rollouts","description":"Run OTA rollouts - attach the basis-point ladder to a live OTA release, drive advance, pause, resume, and halt from the release dashboard, handle the 409 family, and read the OTA dashboard.","frontmatter":{"description":"Run OTA rollouts - attach the basis-point ladder to a live OTA release, drive advance, pause, resume, and halt from the release dashboard, handle the 409 family, and read the OTA dashboard."},"headers":[],"relativePath":"how-to/console/ota-rollouts.md","filePath":"how-to/console/ota-rollouts.md"}'),g={name:"how-to/console/ota-rollouts.md"};function k(m,e,b,T,A,y){const o=i("Mermaid");return a(),r("div",null,[e[1]||(e[1]=t(`<h1 id="run-ota-rollouts" tabindex="-1">Run OTA rollouts <a class="header-anchor" href="#run-ota-rollouts" aria-label="Permalink to &quot;Run OTA rollouts&quot;">​</a></h1><p>An OTA rollout stages a live OTA release across the device fleet on a cumulative ladder — which device lands in which stage is decided deterministically, and the ladder only widens. The model is <a href="/shipperdog/snapshot/concepts/ota-updates">OTA updates</a>; this page drives the controls. Once a plan exists, the release dashboard carries an <strong>OTA staged rollout</strong> block beside the channel curves (see <a href="/shipperdog/snapshot/how-to/console/releases">work with releases</a>).</p><h2 id="attach-the-plan" tabindex="-1">Attach the plan <a class="header-anchor" href="#attach-the-plan" aria-label="Permalink to &quot;Attach the plan&quot;">​</a></h2><p>One rollout plan per OTA release. Attaching happens through the API — the console renders the controls from there:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SHIPPERDOG_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v1/ota/rollouts&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;applicationId&quot;: &quot;&lt;app-uuid&gt;&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;releaseId&quot;: &quot;&lt;release-uuid&gt;&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;mode&quot;: &quot;CHECKPOINT&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;stages&quot;: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          { &quot;basisPoints&quot;: 1000, &quot;note&quot;: &quot;internal canary&quot; },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          { &quot;basisPoints&quot;: 5000 },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          { &quot;basisPoints&quot;: 10000 }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        ]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      }&#39;</span></span></code></pre></div><p>The <code>shipperdog ota promote</code> CLI verb attaches and commences the same plan.</p><ul><li><strong>Stages</strong> — each is a cumulative basis-point threshold (10000 = everyone), strictly ascending, the last exactly 10000: the ladder widens, never retreats. An optional note (1-512 characters) rides each stage.</li><li><strong>Mode</strong> — <code>AUTOMATIC</code> (the policy engine decides between stages) or <code>CHECKPOINT</code> (a Release Manager approves each one).</li><li>The release must be live (ACTIVE or PROMOTED) and carry its OTA bundle — otherwise the attach answers <code>ROLLOUT_RELEASE_NOT_LIVE</code> or <code>ROLLOUT_RELEASE_NOT_OTA</code>.</li></ul><p>A malformed ladder answers <code>INVALID_REQUEST</code> naming every offending field.</p><h2 id="drive-the-rollout" tabindex="-1">Drive the rollout <a class="header-anchor" href="#drive-the-rollout" aria-label="Permalink to &quot;Drive the rollout&quot;">​</a></h2><p>The block shows the status chip (running, paused, halted, complete), the mode badge (<em>automatic (policy-gated)</em> or <em>checkpoint (RM approval)</em>), <strong>stage N of M — X% of the fleet</strong>, each stage&#39;s line with its note and reach time, and the append-only timeline beneath.</p><p><img src="`+c+'" alt="The OTA staged rollout block on the release dashboard"></p>',11)),(a(),l(p,null,{default:s(()=>[d(o,{id:"mermaid-45",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20RUNNING%3A%20attach%20and%20commence%0A%20%20%20%20RUNNING%20--%3E%20PAUSED%3A%20pause%0A%20%20%20%20PAUSED%20--%3E%20RUNNING%3A%20resume%0A%20%20%20%20RUNNING%20--%3E%20HALTED%3A%20halt%20(reason%20required)%0A%20%20%20%20PAUSED%20--%3E%20HALTED%3A%20halt%20(reason%20required)%0A%20%20%20%20HALTED%20--%3E%20RUNNING%3A%20resume%0A%20%20%20%20RUNNING%20--%3E%20COMPLETE%3A%20final%20stage%20reached%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>Every control opens a confirmation dialog; the reason field is audited with the action and <strong>required for halt</strong>:</p><ul><li><strong>Advance</strong> (labeled <strong>Approve and advance</strong> in checkpoint mode) — widen to the next rung. Running plans only.</li><li><strong>Pause</strong> — hold at the current stage: devices already served keep their manifest, new devices still get the current stage, nothing widens.</li><li><strong>Resume</strong> — return a paused or halted plan to running, serving what it had reached; resuming widens nothing by itself.</li><li><strong>Halt</strong> — the human stop. While the plan stands halted, the device check answers no-update for the release. The reason is mandatory and rides the timeline and the audit event.</li></ul><p>Halting is deliberately manual: alert rules page a human through the notification bus, but no threshold ever stops a rollout by itself. Halting stops the rollout; the release itself is pulled back the ordinary way — <a href="/shipperdog/snapshot/how-to/console/rollback">roll back a release</a>.</p><h2 id="when-the-console-answers-409" tabindex="-1">When the console answers 409 <a class="header-anchor" href="#when-the-console-answers-409" aria-label="Permalink to &quot;When the console answers 409&quot;">​</a></h2><p>Control actions are guarded by the rollout&#39;s own 409 family (details verbatim from the <a href="/shipperdog/snapshot/reference/error-codes">error-code registry</a>):</p><table tabindex="0"><thead><tr><th>Code</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td><code>ROLLOUT_CONFLICT</code></td><td>The rollout plan already exists or changed concurrently; reload and retry.</td><td>One plan per release. On a control race the console re-reads the plan — act on the fresh state.</td></tr><tr><td><code>ROLLOUT_ACTION_INVALID</code></td><td>The action is not valid for the plan&#39;s standing.</td><td>Check the status chip — a complete plan accepts no controls.</td></tr><tr><td><code>ROLLOUT_BLOCKED</code></td><td>The advancement is blocked: resolve the policy rule first.</td><td>The AUTOMATIC mode&#39;s policy refusal — the evidence rides the error detail.</td></tr><tr><td><code>ROLLOUT_RELEASE_NOT_LIVE</code></td><td>The release is not distributing; a rollout plan commences on a live (ACTIVE or PROMOTED) release.</td><td>Attach once the release is live.</td></tr><tr><td><code>ROLLOUT_RELEASE_NOT_OTA</code></td><td>The release carries no OTA bundle; rollout plans belong to OTA releases.</td><td>Check the release&#39;s ring channel and its bundle.</td></tr></tbody></table><h2 id="read-the-ota-dashboard" tabindex="-1">Read the OTA dashboard <a class="header-anchor" href="#read-the-ota-dashboard" aria-label="Permalink to &quot;Read the OTA dashboard&quot;">​</a></h2><p>Open it from <strong>Tenants</strong> — the <strong>OTA</strong> action on a tenant&#39;s row. Pick the application and bundle (SIGNED-and-later bundles); an optional ring filter narrows the funnel to one ring&#39;s devices. The view is live, refreshing every 30 seconds.</p><p><img src="'+u+'" alt="The OTA dashboard"></p><ul><li><strong>Alerts</strong> — severity badges (critical, warning, info), the standing firings, and the recent resolved history, each with its rule expression, observed value, and times. The rules are authored on the <a href="/shipperdog/snapshot/how-to/console/ota-bundles">OTA bundles screen</a>.</li><li><strong>Device funnel</strong> — Checks (counted server-side) beside the device-reported journey: devices seen, downloads, applied, with the failed and rolled-back totals and the apply success rate — applied over applied-plus-failed.</li><li><strong>Failure reasons</strong> — failed applies broken down by reason (<code>checksum_mismatch</code>, <code>signature_invalid</code>, <code>apply_error</code>, for example).</li><li><strong>Adoption over time</strong> — the daily curve of devices carrying the bundle.</li><li><strong>Crash-rate comparison</strong> — the new bundle against the current released one: crash-free rate, sessions, crashes on both sides, and the delta in percentage points. A negative delta is the halt signal; a comparison needs both sides present.</li></ul><p>The organization and tenant rollups live on <a href="/shipperdog/snapshot/how-to/console/analytics-and-dashboards">the dashboards</a>; the OTA dashboard is the per-bundle grain beneath them.</p><p><strong>Related guides:</strong><a href="/shipperdog/snapshot/how-to/console/ota-bundles">manage OTA bundles</a> · <a href="/shipperdog/snapshot/how-to/console/staged-rollout">run a staged tenant rollout</a> · <a href="/shipperdog/snapshot/how-to/console/analytics-and-dashboards">read the dashboards</a> · <a href="/shipperdog/snapshot/concepts/ota-updates">OTA updates concepts</a></p>',12))])}const f=n(g,[["render",k]]);export{E as __pageData,f as default};
